"URC（Unsolicited Result Code）": "URC (Unsolicited Result Code)",
"URC = Unsolicited Result Code（非請求結果碼）：模組「未經請求就主動吐出」的訊息，不是任何指令的回應 —— 開機的 RDY／+CPIN: READY、簡訊到達、TCP 資料到達、Wi-Fi 掃描結果都是。這組管 URC 的輸出埠與總開關；輸出埠不是 uart1 時，本工具（走 UART）一條 URC 都收不到。": "URC = Unsolicited Result Code (非請求結果コード): モジュールが「要求されずに自発的に出力する」メッセージで、どのコマンドの応答でもない — 起動時の RDY / +CPIN: READY、SMS 着信、TCP データ着信、Wi-Fi スキャン結果はすべて URC。ここでは URC の出力ポートと総括スイッチを管理する。出力ポートが uart1 でない場合、本ツール (UART 経由) は URC を 1 件も受け取れない。",
