"按右側 ▾ 展開全部選項，也可直接在欄位打字。清單預設是手冊 §2.24 的三個通用埠；跑過上面的 AT+QURCCFG=? 之後，會自動換成本機實際回報的清單（例如支援 \"all\" 的機型會多一項）": "右の ▾ で全選択肢を展開。欄に直接入力も可。既定のリストはマニュアル §2.24 の汎用 3 ポート。上の AT+QURCCFG=? を実行すると実機の応答リストに自動で置き換わる (\"all\" 対応機種では項目が増える)",
