"把 AT 設定重置為原廠值 —— 接手一顆被亂設過的模組時的第一步": "AT 設定を工場出荷値へリセット — 設定が荒れたモジュールを引き継いだときの第一歩",
"SIM 卡狀態：READY 表示可用；無卡回 +CME ERROR: 10": "SIM カードの状態: READY なら使用可。カード無しは +CME ERROR: 10 を返す",
"PIN／PUK 剩餘嘗試次數（手冊範圍 PIN 0-3、PUK 0-10）": "PIN / PUK の残り試行回数 (マニュアル範囲 PIN 0-3、PUK 0-10)",
