"SIM 卡的 PIN 碼，一般 4-8 位數字。只填數字，引號由程式加上。連續輸錯會扣減剩餘次數，歸零就要用 PUK 解": "SIM カードの PIN コード。通常 4-8 桁の数字。数字のみ入力し、引用符はプログラムが付加する。連続で誤ると残り回数が減り、0 になると PUK での解除が必要",
