"供電電壓（mV）；部分韌體不支援、回 ERROR 屬正常": "電源電圧 (mV)。一部ファームウェアは非対応で、ERROR を返すのは正常",
"網路同步推算的目前本地時間（AT+CCLK? 是模組自己的 RTC，來源不同）": "ネットワーク同期から算出した現在のローカル時刻 (AT+CCLK? はモジュール自身の RTC で、取得元が異なる)",
"訊號強度：rssi 0-31 對應 -113~-51 dBm，99=未知": "信号強度: rssi 0-31 が -113~-51 dBm に対応、99=不明",
"LTE/EPS 網路註冊狀態（4G 模組看這個最準）：1=本網、5=漫遊": "LTE/EPS ネットワーク登録状態 (4G モジュールはこれが最も確実): 1=在圏、5=ローミング",
"電路交換域註冊狀態：1=本網、5=漫遊、2=搜尋中、3=被拒": "回線交換ドメインの登録状態: 1=在圏、5=ローミング、2=サーチ中、3=拒否",
