"MQTT broker 的域名或 IP，四個選項都免費、允許匿名、不必註冊（2026-08-07 全部實機實測：四家從模組都連得上 TCP 1883）。預設 mqttgo.io 是台灣本地服務，對台灣使用者延遲最低。⚠ 這些都是「完全公開」的 broker —— 任何人都能訂閱你發布的主題，也可能有別人的訊息混進來，測試時「絕對不要送真實資料」，主題請加隨機尾碼。TLS 埠：mqttgo.io 與其餘皆為 8883（mosquitto 免 CA 驗證的是 8886）。": "MQTT ブローカーのドメイン名または IP。4 つとも無料・匿名接続可・登録不要（2026-08-07 に実機で全数検証済み：4 社すべてモジュールから TCP 1883 に到達）。既定の mqttgo.io は台湾国内のサービスで、台湾のユーザーには最も低遅延。⚠ いずれも完全公開のブローカーです —— あなたが publish したトピックは誰でも subscribe でき、他人のメッセージが混ざることもあります。テスト中は実データを絶対に送らず、トピックにはランダムな接尾辞を付けてください。TLS ポート：mqttgo.io ほかは 8883（mosquitto の CA 検証不要ポートは 8886）。",
