"TCP client 收發。本組全部走 buffer 模式（QIOPEN 末參數 0）—— ⚠ 收到的資料「不會」自己出現在終端機：模組只發一則 +QIURC: \"recv\",<id> 通知，要自己按 Read Data（AT+QIRD）才取得出來，而且要重複讀到回 +QIRD: 0 為止，否則模組不會再發下一次通知。收不到通知就先查 Hardware 頁的 AT+QURCCFG=\"urcport\" 是不是 uart1 —— 不是的話 URC 全跑到 USB 埠去了。另外，預設對端 tcpbin.com 是「以行為單位」的 echo 伺服器，送出的資料結尾沒有換行（hex 0A）它就一直緩衝著不回送（實測：不加 0A 等 6 秒無回應，補一個 0A 後 0.1 秒立刻收到）。": "TCP client の送受信。この組はすべて buffer モード (QIOPEN の末尾パラメータ 0) — ⚠ 受信したデータは端末に「自動では表示されない」: モジュールは +QIURC: \"recv\",<id> の通知を 1 件出すだけで、自分で Read Data (AT+QIRD) を押さないと取り出せない。しかも +QIRD: 0 が返るまで繰り返し読まないと、モジュールは次の通知を出さない。通知が届かないときは、まず Hardware ページの AT+QURCCFG=\"urcport\" が uart1 かどうかを確認する — uart1 でなければ URC はすべて USB ポートへ流れている。なお、既定の接続先 tcpbin.com は「行単位」で動く echo サーバで、送信データの末尾に改行 (hex 0A) がないと、ずっとバッファに溜めたまま返してこない (実測: 0A を付けないと 6 秒待っても無応答、0A を 1 個足すと 0.1 秒で即座に受信)。",
"TCP keepalive：啟用；閒置 {0} 秒開始探測、每 {1} 秒一次、最多 {2} 次": "TCP keepalive: 有効。アイドル {0} 秒でプローブ開始、{1} 秒ごとに 1 回、最大 {2} 回",
"TCP 層的保活探測（手冊 §2.3.1 AT+QICFG=\"tcp/keepalive\"）。⚠ 對 tcpbin.com 的 15 秒閒置逾時「完全沒用」—— 實測開了 keepalive 仍然在 15.1 秒被關：keepalive 送的是 TCP 層的空探測封包，應用程式根本看不到，而 tcpbin 數的是「有沒有收到應用資料」；何況 interval_time 最小 25 秒，本來就大於 15 秒。要撐過應用層逾時只能送真資料（例如每 10 秒 AT+QISENDEX=0,\"0A\" 送一個換行）。它真正有用的地方是「電信商 NAT 保活與偵測死連線」—— IoT 卡的 NAT 對應閒置數分鐘就會被回收，那是另一個層次的斷線。參數範圍取自手冊；按 QICFG=? 可看這顆韌體實際回報的範圍（零流量）。": "TCP 層の keepalive プローブ (マニュアル §2.3.1 AT+QICFG=\"tcp/keepalive\")。⚠ tcpbin.com の 15 秒アイドルタイムアウトには「まったく効かない」 — 実測では keepalive を有効にしても 15.1 秒で閉じられた: keepalive が送るのは TCP 層の空のプローブパケットでアプリケーションからは見えず、tcpbin が数えているのは「アプリケーションのデータを受け取ったかどうか」だから。そもそも interval_time は最小 25 秒で、はじめから 15 秒より大きい。アプリケーション層のタイムアウトを乗り切るには本物のデータを送るしかない (例: 10 秒ごとに AT+QISENDEX=0,\"0A\" で改行を 1 個送る)。本当に役立つのは「通信事業者の NAT 保持と、死んだ接続の検出」 — IoT SIM の NAT マッピングは数分アイドルすると回収され、それは別の層の切断になる。パラメータ範囲はマニュアルによる。QICFG=? を押せば、このファームウェアが実際に報告する範囲を確認できる (通信量ゼロ)。",
