"以 PDP 1、SSL context 1 連指定主機與埠，末碼 1＝直推模式，收到資料直接由 +QSSLURC 連同內容吐出，不需再下 QSSLRECV 讀取。": "PDP 1、SSL context 1 で指定ホストとポートへ接続。末尾の 1＝直接プッシュモードで、受信データは +QSSLURC が内容ごと出力するため、QSSLRECV を送る必要がない。",
"以 hex 字串送資料到 connectID 0；單行免資料模式 —— QISEND 要 Ctrl+Z，本工具送不出，一律用這個": "hex 文字列で connectID 0 にデータを送る。1 行完結のデータ入力不要モード — QISEND は Ctrl+Z が必要で本ツールでは送れないため、常にこちらを使う",
"以十六進位字串向 connectID 0 送出 5 位元組，字串上限 512 bytes": "十六進文字列で connectID 0 に 5 バイト送信。文字列の上限は 512 bytes",
