"兩段式設 URL：等 CONNECT 再送 23 bytes。有 GET/POST 進行中不會給 CONNECT；別的埠佔著 data mode 回錯誤 704": "2 段階で URL を設定: CONNECT を待ってから 23 bytes を送る。GET/POST が進行中だと CONNECT は出ない。他のポートが data mode を占有しているとエラー 704",
"兩段式設 URL：等 CONNECT 再送 {0} bytes（不可附加 CR/LF，會被算進長度）。有 GET/POST 進行中不會給 CONNECT；別的埠佔著 data mode 回錯誤 704": "2 段階の URL 設定：CONNECT を待ってから {0} バイト送ります（CR/LF を付けないでください。長さに数えられます）。GET/POST 実行中は CONNECT が返りません。別のポートがデータモードを占有しているとエラー 704 になります",
"分段 GET：從位移 {0} 取 {1} bytes（走 HTTP Range，成功時伺服器回 206）。⚠ 只在 QHTTPCFG=\"requestheader\",0 時可執行；伺服器不支援 Range 就會回 200 加整份內容（實測 httpbin /base64 即如此，要用 /range/N 才驗得到）": "分割 GET：オフセット {0} から {1} バイト取得（HTTP Range を使用、成功時サーバーは 206 を返します）。⚠ QHTTPCFG=\"requestheader\",0 のときだけ実行できます。Range 非対応のサーバーは 200 と全文を返します（httpbin /base64 で実測。きちんと検証するには /range/N を使ってください）",
"功能等級：{0}": "機能レベル: {0}",
"原廠重置設定檔": "工場出荷リセット用プロファイル",
"去活化 PDP context；只有要徹底重置網路時才按": "PDP context を非活性化。ネットワークを完全にリセットしたいときだけ押す",
"取出 {0} bytes，資料接在下一行；要重複讀到回 0 為止": "{0} bytes 取り出した。データは次の行に続く。0 が返るまで繰り返し読むこと",
"只查 clientID 4 這一條連線，回報遠端位址與埠、本地埠、狀態碼、PDP 與 SSL context ID 及所用 AT 埠。": "clientID 4 の接続だけを確認。リモートアドレスとポート、ローカルポート、状態コード、PDP と SSL context ID、使用中の AT ポートを通知する。",
"只查 clientID {0} 這一條連線，回報遠端位址與埠、本地埠、狀態碼、PDP 與 SSL context ID 及所用 AT 埠。": "clientID {0} のこの 1 本だけを照会し、リモートのアドレスとポート、ローカルポート、状態コード、PDP と SSL の context ID、使用中の AT ポートを返します。",
