"同一 SSL context 的連線全關後，模組才釋放該 context": "同じ SSL context 上の接続がすべて閉じられて初めて、モジュールはその context を解放します",
"命令列結束字元": "コマンドライン終端文字",
"啟用 AGNSS —— 冷啟動縮到秒-分級；重開機生效、寫 NVRAM": "AGNSS を有効化 — コールドスタートが秒〜分オーダーに短縮。再起動で反映、NVRAM に書き込み",
"啟用 PDP context，最長要等 150 秒": "PDP context を有効化。最大 150 秒待つ必要がある",
"啟用 TCP keepalive（閒置秒數／探測間隔／探測次數）—— 這是 TCP 層探測，擋不住伺服器的「應用層」閒置逾時，用途是電信商 NAT 保活與偵測死連線": "TCP keepalive を有効化 (アイドル秒数 / プローブ間隔 / プローブ回数) — これは TCP 層のプローブで、サーバの「アプリケーション層」アイドルタイムアウトは防げない。用途は通信事業者の NAT 保持と、死んだ接続の検出",
"啟用 TCP keepalive；⚠ 擋不住 tcpbin 那種應用層閒置逾時，用途是電信商 NAT 保活": "TCP keepalive を有効化。⚠ tcpbin のようなアプリケーション層のアイドルタイムアウトは防げない。用途は通信事業者の NAT 保持",
"啟用後（要重開機才生效）每次 GNSS 啟動會從網路下載輔助資料：需要已啟用的 PDP context，並消耗數據流量（1NCE 漫遊卡計費，單次約數十 KB）。": "有効化すると (反映には再起動が必要) GNSS 起動のたびにネットワークから支援データを取得する: 有効な PDP context が必要で、データ通信量を消費する (1NCE ローミング SIM は課金対象。1 回あたり数十 KB 程度)。",
