"實際送出的位元組。長度以 UTF-8 計並自動填入指令的 <sendlen>（中文字算 3 bytes），上限 1460 bytes（手冊 §2.2.3）。注意：本欄是文字輸入框，打不出 CR/LF 等控制字元，所以像 HTTP 請求那種需要以 \\r\\n\\r\\n 收尾的協定送不完整。": "実際に送信するバイト列。長さは UTF-8 で数えてコマンドの <sendlen> に自動で入る (日本語は 1 文字 3 bytes)。上限 1460 bytes (マニュアル §2.2.3)。注意: この欄はテキスト入力欄なので CR/LF などの制御文字を入力できず、HTTP リクエストのように \\r\\n\\r\\n で終端する必要があるプロトコルは完全な形で送れない。",
