"從位移 0 取 512 的分段 GET（手冊未標單位與範圍，需實測）；會實際連線並消耗流量": "オフセット 0 から 512 を取る分割 GET (マニュアルに単位と範囲の記載がなく、実測が必要)。実際に接続し、通信量を消費する",
