"轉命令模式、保留連線": "コマンドモードへ移行、接続は維持",
"退格字元": "バックスペース文字",
"退訂": "アンサブスクライブ",
"送出": "送信",
"送出 {0} bytes／接收 {1} bytes": "送信 {0} bytes／受信 {1} bytes",
"送出（兩段式）": "送信 (2 段階)",
"送資料（兩段式：等 > 再送本文，免 Ctrl+Z）": "データ送信 (2 段階: > を待ってから本文を送る。Ctrl+Z 不要)",
"這是 AT+{0}=? 回報的「參數允許範圍」，不是目前設定值": "これは AT+{0}=? が返す「パラメータの許容範囲」であって、現在の設定値ではありません",
"這會真的連上伺服器抓資料，直接消耗 1NCE 預付流量。URC 裡的 <content_length> 就是回應 body 的位元組數，先確認 URL 指向的是小檔案再按。": "これは実際にサーバへ接続してデータを取得し、1NCE のプリペイド通信量を直接消費する。URC の <content_length> が応答 body のバイト数。URL が小さいファイルを指していることを確認してから押すこと。",
"連線 {0} TLS 交握完成，可以開始收送資料": "接続 {0} の TLS ハンドシェイク完了。データの送受信を開始できる",
"連線 {0} → {1}:{2}（本地埠 {3}）；": "接続 {0} → {1}:{2} (ローカルポート {3})。",
"連線 {0} 已斷（對端關閉或 PDP 去激活）；狀態會停在 closing，": "接続 {0} は切断された (対向がクローズ、または PDP 非活性化)。状態は closing のまま止まるので、",
"連線 {0} 已被對端關閉；狀態會停在 closing，要下 AT+QICLOSE={1} 才回 initial": "接続 {0} は対向に閉じられた。状態は closing のまま止まるので、AT+QICLOSE={1} を送らないと initial に戻らない",
"連線 {0} 建立失敗 —— 錯誤 {1}：{2}": "接続 {0} の確立に失敗 — エラー {1}: {2}",
"連線 {0} 建立成功": "接続 {0} の確立に成功",
"連線 {0} 建立成功 —— 可以開始用 AT+QISENDEX 送資料": "接続 {0} の確立に成功 — AT+QISENDEX でデータを送り始められる",
"連線 {0} 收到 {1} bytes（direct push 模式）—— 資料緊接在下一行": "接続 {0} が {1} bytes 受信 (direct push モード) — データはすぐ次の行",
"連線 {0} 收到資料 —— 用 AT+QIRD 取出，要一直讀到回 0 才會再有新通知": "接続 {0} がデータを受信 — AT+QIRD で取り出す。0 が返るまで読み続けないと、次の通知が来ない",
"連線 {0} 收到資料（buffer 模式）—— 用 AT+QSSLRECV 取出，模組不會自己吐": "接続 {0} がデータを受信 (buffer モード) — AT+QSSLRECV で取り出す。モジュールは自分では出力しない",
"連線 {0} 開啟失敗 —— 錯誤 {1}：{2}": "接続 {0} のオープンに失敗 — エラー {1}: {2}",
"遠端伺服器的域名或 IP。域名會走 DNS，解析失敗回錯誤碼 565。手冊範例用的 192.0.2.2 是文件保留位址，不是真實伺服器。": "リモートサーバのドメイン名または IP。ドメイン名は DNS を通り、解決に失敗するとエラーコード 565 を返す。マニュアルの例にある 192.0.2.2 はドキュメント用予約アドレスで、実在のサーバではない。",
"遠端伺服器的域名或 IP。與 buffer 模式的差別只在最後一個參數 <access_mode>=1：收到的資料由模組直接以 URC 吐出，不必再下 AT+QSSLRECV。": "リモートサーバのドメイン名または IP。buffer モードとの違いは最後のパラメータ <access_mode>=1 だけ: 受信データはモジュールが URC で直接出力するので、AT+QSSLRECV を送る必要がない。",
